import{_ as d,o as r,c as e,a2 as a}from"./chunks/framework.mRCPFc5l.js";const _=JSON.parse('{"title":"2. 基础设定与游戏规则","description":"","frontmatter":{},"headers":[],"relativePath":"rules.md","filePath":"rules.md"}'),o={name:"rules.md"};function l(c,t,i,n,s,h){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="_2-基础设定与游戏规则" tabindex="-1">2. 基础设定与游戏规则 <a class="header-anchor" href="#_2-基础设定与游戏规则" aria-label="Permalink to &quot;2. 基础设定与游戏规则&quot;">​</a></h1><h2 id="_2-1-核心参数" tabindex="-1">2.1 核心参数 <a class="header-anchor" href="#_2-1-核心参数" aria-label="Permalink to &quot;2.1 核心参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>当前值</th></tr></thead><tbody><tr><td>难度</td><td>主世界困难；下界/末地简单；主城和平</td></tr><tr><td>死亡掉落</td><td><strong>关闭</strong>，死亡后保留背包物品</td></tr><tr><td>野外 PvP</td><td>开启</td></tr><tr><td>领地内 PvP</td><td>默认关闭，可由领地旗标开启</td></tr><tr><td>爆炸破坏方块</td><td><strong>默认关闭，领地内可开启</strong>：领地默认不允许爆炸破坏方块，屋主可在自己领地的设置里开启，开启后该领地内爆炸会破坏方块</td></tr><tr><td>火焰蔓延</td><td><strong>默认关闭，领地内可开启</strong>：全服默认不自然蔓延；屋主可在自己领地内开启，但最终仍受服务器设置限制</td></tr><tr><td>世界边界</td><td>主世界 100,000 格宽；下界 12,500 格宽；末地 50,000 格宽</td></tr><tr><td>服务器人数上限</td><td>1,000（服务器列表里显示的 2,333 只是展示值）</td></tr><tr><td>白名单</td><td>关闭</td></tr><tr><td>视距</td><td>10 格</td></tr></tbody></table><blockquote><p>死亡不会掉落背包物品；但药水效果、位置和时间仍会损失。困难难度下怪物伤害较高，下界与末地尤其危险。</p><p>默认情况下爆炸不破坏方块、火焰不自然蔓延，但仍会伤害实体。领地屋主可以在自己领地的设置里开启爆炸破坏与火焰蔓延（火焰蔓延最终仍受服务器设置限制）。请勿在主城或他人建筑附近点燃 TNT 或生火。</p></blockquote><h2 id="_2-2-社区约定-非官方规则" tabindex="-1">2.2 社区约定（非官方规则） <a class="header-anchor" href="#_2-2-社区约定-非官方规则" aria-label="Permalink to &quot;2.2 社区约定（非官方规则）&quot;">​</a></h2><p>以下内容是社区通行做法，<strong>不是管理组正式规则</strong>；具体处理由管理组公告决定。</p><ul><li>不偷窃、不破坏他人领地，不绕过领地保护。</li><li>不利用漏洞、复制物品或刷取经济；发现漏洞请报告管理组。</li><li>不刷屏、不发布广告、不进行人身攻击。</li><li>野外可以 PvP，但不要在他人明确表示不愿对战后持续骚扰。</li><li>大型红石、大量实体或高频操作请控制规模，避免影响其他玩家。</li><li>进入他人领地前先打招呼；未经允许不要拿取容器物品。</li></ul><h2 id="_2-3-基础常用命令" tabindex="-1">2.3 基础常用命令 <a class="header-anchor" href="#_2-3-基础常用命令" aria-label="Permalink to &quot;2.3 基础常用命令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/spawn</code></td><td>回主城出生点</td></tr><tr><td><code>/back</code></td><td>回上一个传送点或死亡点</td></tr><tr><td><code>/warp court</code></td><td>去主城观景台</td></tr><tr><td><code>/warps</code></td><td>查看可用传送点</td></tr><tr><td><code>/tpa &lt;玩家&gt;</code></td><td>请求传送到对方</td></tr><tr><td><code>/tpahere &lt;玩家&gt;</code></td><td>请求对方传送到你</td></tr><tr><td><code>/tpaccept / /tpyes</code></td><td>接受传送请求</td></tr><tr><td><code>/tpdeny / /tpno</code></td><td>拒绝传送请求</td></tr><tr><td><code>/tpignore</code></td><td>忽略他人的传送请求</td></tr><tr><td><code>/help</code></td><td>查看服务器命令帮助</td></tr></tbody></table>',9)])])}const u=d(o,[["render",l]]);export{_ as __pageData,u as default};
